mapper.insert:
CREATE TABLE IF NOT EXISTS asset_download_daily
(
  download_day   DATE         NOT NULL,
  format         VARCHAR(100) NOT NULL,
  repository_id  INT          NOT NULL,
  component_id   INT          NOT NULL,
  download_count BIGINT       NOT NULL,

  CONSTRAINT pk_asset_download_daily PRIMARY KEY (download_day, format, repository_id, component_id)
);

CREATE INDEX IF NOT EXISTS idx_asset_download_daily_repository ON asset_download_daily (format, repository_id);

CREATE TABLE IF NOT EXISTS asset_download_daily
(
  download_day   DATE         NOT NULL,
  format         VARCHAR(100) NOT NULL,
  repository_id  INT          NOT NULL,
  component_id   INT          NOT NULL,
  download_count BIGINT       NOT NULL,

  CONSTRAINT pk_asset_download_daily PRIMARY KEY (download_day, format, repository_id, component_id)
);


DO $$
BEGIN
  IF to_regclass('idx_asset_download_daily_repository') IS NULL THEN
    CREATE INDEX idx_asset_download_daily_repository ON asset_download_daily (format, repository_id);
  END IF;
END
$$;

mapper.select:
SELECT format, repository_id, download_day, SUM(download_count) AS download_count
  FROM asset_download_daily
 WHERE download_day >= #{from}
 GROUP BY format, repository_id, download_day;

SELECT format, repository_id, SUM(download_count) AS download_count,
       COUNT(DISTINCT NULLIF(component_id, 0)) AS component_count
  FROM asset_download_daily
 WHERE download_day >= #{from}
 GROUP BY format, repository_id;

SELECT format, repository_id, component_id, SUM(download_count) AS download_count
  FROM asset_download_daily
 WHERE download_day >= #{from}
   AND format = #{format}
   AND component_id <> 0
   AND repository_id IN
#{repositoryId}
 GROUP BY format, repository_id, component_id
 ORDER BY SUM(download_count) DESC, component_id
 LIMIT #{limit};

mapper.delete:
DELETE FROM asset_download_daily
 WHERE format = #{format}
   AND repository_id = #{repositoryId};
